def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]

    # Find connected components of all non-background cells.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x, grid[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            components.append(comp)

    if not components:
        return out
    shape_comp = max(components, key=len)
    sr = min(y for y,x,v in shape_comp)
    sc = min(x for y,x,v in shape_comp)
    shape = [(y-sr, x-sc, v) for y,x,v in shape_comp]
    center_r = (min(y for y,x,v in shape) + max(y for y,x,v in shape)) // 2
    center_c = (min(x for y,x,v in shape) + max(x for y,x,v in shape)) // 2

    for comp in components:
        if comp is shape_comp:
            continue
        for r, c, _ in comp:
            for dy, dx, value in shape:
                nr, nc = r + dy - center_r, c + dx - center_c
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = value
    return out
